    int getForwardEvolutions(Enums::GameVersion group, uint16_t speciesId, uint8_t formId,
                             ForwardEvolution* outEvolutions, int maxEvolutions) {
        ForwardEvolutionTable table{};
        if (outEvolutions == nullptr || maxEvolutions <= 0 || !lookupForwardTable(group, table)) {
            return 0;
        }
        uint32_t low = 0, high = table.count;
        while (low < high) {
            const uint32_t middle = low + ((high - low) >> 1);
            const ForwardEvolution& row = table.rows[middle];
            if (row.speciesId < speciesId || (row.speciesId == speciesId && row.formId < formId)) {
                low = middle + 1;
            } else {
                high = middle;
            }
        }
        int writtenCount = 0;
        for (uint32_t rowIndex = low; rowIndex < table.count && writtenCount < maxEvolutions; ++rowIndex) {
            const ForwardEvolution& row = table.rows[rowIndex];
            if (row.speciesId != speciesId || row.formId != formId) {
                break;
            }
            outEvolutions[writtenCount] = row;
            ++writtenCount;
        }
        return writtenCount;
    }
